+#!/usr/bin/env bash
+# Fresh environment smoke test for kspec v0.11.0
+# Runs in a podman container to simulate a clean install.
+set -euo pipefail
+
+KSPEC_VERSION="${1:-0.11.0}"
+CONTAINER_NAME="kspec-smoke-test"
+IMAGE="docker.io/library/node:22-slim"
+
+echo "=== kspec v${KSPEC_VERSION} fresh environment smoke test ==="
+echo ""
+
+# Clean up any previous run
+podman rm -f "$CONTAINER_NAME" 2>/dev/null || true
+
+# Launch container
+podman run -d --name "$CONTAINER_NAME" "$IMAGE" sleep 3600
+
+run() {
+  podman exec "$CONTAINER_NAME" bash -c "$1"
+}
+
+section() {
+  echo ""
+  echo "--- $1 ---"
+}
+
+pass() { echo "  PASS: $1"; }
+fail() { echo "  FAIL: $1"; FAILURES=$((FAILURES + 1)); }
+FAILURES=0
+
+# Phase 1: Install
+section "Phase 1: Install kspec from npm"
+run "npm install -g @kynetic-ai/spec@${KSPEC_VERSION} 2>&1" && pass "npm install" || fail "npm install"
+run "kspec --version" && pass "kspec binary available" || fail "kspec binary not found"
+VERSION=$(run "kspec --version 2>&1" || true)
+echo "  Installed version: $VERSION"
+
+# Phase 2: Init a new project
+section "Phase 2: Initialize new project"
+run "apt-get update -qq && apt-get install -y -qq git >/dev/null 2>&1" && pass "git installed" || fail "git install"
+run "mkdir -p /workspace && cd /workspace && git init && git config user.name test && git config user.email test@test.com && git commit --allow-empty -m init" \
+  && pass "git repo created" || fail "git repo creation"
+run "cd /workspace && kspec init --project-name smoke-test 2>&1" && pass "kspec init" || fail "kspec init"
+run "test -d /workspace/.kspec" && pass ".kspec directory exists" || fail ".kspec directory missing"
+
+# Phase 3: Basic CLI operations
+section "Phase 3: CLI operations"
+run "cd /workspace && kspec task add --title 'Test task 1' --tag smoke 2>&1" && pass "task add" || fail "task add"
+run "cd /workspace && kspec task add --title 'Test task 2' --priority 1 --tag smoke 2>&1" && pass "task add (p1)" || fail "task add (p1)"
+run "cd /workspace && kspec task list 2>&1" && pass "task list" || fail "task list"
+TASK_COUNT=$(run "cd /workspace && kspec task list --json 2>&1 | node -e \"process.stdin.on('data',d=>{try{const j=JSON.parse(d);console.log((j.items||j).length)}catch{console.log(0)}})\"" || echo "0")
+echo "  Tasks found: $TASK_COUNT"
+[[ "$TASK_COUNT" -ge 2 ]] && pass "task count >= 2" || fail "expected >= 2 tasks, got $TASK_COUNT"
+
+run "cd /workspace && kspec inbox add 'Test inbox item' --tag smoke 2>&1" && pass "inbox add" || fail "inbox add"
+run "cd /workspace && kspec inbox list 2>&1" && pass "inbox list" || fail "inbox list"
+
+# Phase 4: Spec items
+section "Phase 4: Spec items"
+run "cd /workspace && kspec item add --title 'Test feature' --type feature --module core 2>&1" && pass "item add" || fail "item add"
+run "cd /workspace && kspec item list 2>&1" && pass "item list" || fail "item list"
+
+# Phase 5: Export
+section "Phase 5: Export (snapshot)"
+run "cd /workspace && kspec export --format json --include-validation -o /workspace/snapshot.json 2>&1" && pass "export json" || fail "export json"
+SNAPSHOT_KEYS=$(run "cd /workspace && node -e \"const d=require('./snapshot.json');console.log(Object.keys(d).join(','))\"" || echo "error")
+echo "  Snapshot keys: $SNAPSHOT_KEYS"
+SNAP_SIZE=$(run "wc -c < /workspace/snapshot.json" || echo "0")
+echo "  Snapshot size: ${SNAP_SIZE} bytes"
+
+# Phase 6: Daemon
+section "Phase 6: Daemon"
+run "cd /workspace && kspec serve start 2>&1" && pass "daemon start" || fail "daemon start"
+sleep 2
+HEALTH=$(run "curl -s http://localhost:3456/api/health 2>&1" || echo "error")
+echo "  Health response: $HEALTH"
+echo "$HEALTH" | grep -q '"status"' && pass "daemon health check" || fail "daemon health check"
+
+# Test task API
+TASKS_API=$(run "curl -s 'http://localhost:3456/api/tasks?limit=5' 2>&1" || echo "error")
+echo "$TASKS_API" | grep -q '"items"' && pass "GET /api/tasks" || fail "GET /api/tasks"
+
+# Test items API
+ITEMS_API=$(run "curl -s 'http://localhost:3456/api/items?limit=5' 2>&1" || echo "error")
+echo "$ITEMS_API" | grep -q '"items"' && pass "GET /api/items" || fail "GET /api/items"
+
+# Test meta APIs
+META_CONFIG=$(run "curl -s http://localhost:3456/api/meta/config 2>&1" || echo "error")
+echo "$META_CONFIG" | grep -q '"project"' && pass "GET /api/meta/config" || fail "GET /api/meta/config"
+
+META_SHADOW=$(run "curl -s http://localhost:3456/api/meta/shadow 2>&1" || echo "error")
+echo "$META_SHADOW" | grep -q '"enabled"' && pass "GET /api/meta/shadow" || fail "GET /api/meta/shadow"
+
+# Phase 7: Web UI
+section "Phase 7: Web UI static assets"
+UI_INDEX=$(run "curl -s http://localhost:3456/ 2>&1" || echo "error")
+echo "$UI_INDEX" | grep -q '<html' && pass "UI index.html served" || fail "UI index.html not served"
+echo "$UI_INDEX" | grep -q 'app.css\|_app' && pass "UI has CSS/JS references" || fail "UI missing asset references"
+
+# Test a few UI routes (SPA fallback)
+UI_TASKS=$(run "curl -s http://localhost:3456/tasks 2>&1" || echo "error")
+echo "$UI_TASKS" | grep -q '<html' && pass "UI /tasks route" || fail "UI /tasks route"
+
+UI_BOARD=$(run "curl -s http://localhost:3456/tasks/board 2>&1" || echo "error")
+echo "$UI_BOARD" | grep -q '<html' && pass "UI /tasks/board route" || fail "UI /tasks/board route"
+
+UI_SETTINGS=$(run "curl -s http://localhost:3456/settings 2>&1" || echo "error")
+echo "$UI_SETTINGS" | grep -q '<html' && pass "UI /settings route" || fail "UI /settings route"
+
+# Phase 8: Cleanup
+section "Phase 8: Daemon stop"
+run "cd /workspace && kspec serve stop 2>&1" && pass "daemon stop" || fail "daemon stop"
+
+# Summary
+echo ""
+echo "==============================="
+if [[ $FAILURES -eq 0 ]]; then
+  echo "ALL TESTS PASSED"
+else
+  echo "FAILURES: $FAILURES"
+fi
+echo "==============================="
+
+# Cleanup container
+podman rm -f "$CONTAINER_NAME" >/dev/null 2>&1
+
+exit $FAILURES
